SETTINGS_CSS = r'''
/* Bento visual system: automation settings — approved reference v2. */
:root{--focus:#2857b3}html[data-theme="night"]{--focus:#aec4ff}
.shell{width:calc(100% - 48px);max-width:1320px;min-height:calc(100dvh - 40px);margin:20px auto;padding:26px;border:1px solid var(--white-line);border-radius:24px;background:rgba(247,249,255,.61);box-shadow:var(--shadow)}
header{padding:22px;border:1px solid var(--white-line);border-radius:18px;background:linear-gradient(118deg,#e0edff,#edf7ff 36%,#eae7ff 80%,#e0f7fb);align-items:center;gap:18px}
h1{font-size:28px;letter-spacing:-.025em;margin:6px 0 7px;line-height:1.25}.eyebrow{font-size:12px;color:var(--blue);letter-spacing:0}.header-actions{gap:9px;flex-wrap:wrap;justify-content:flex-end}.header-actions .nav-link{min-height:39px;border:1px solid var(--line);border-radius:11px;padding:0 12px;background:var(--surface);color:var(--ink);text-decoration:none;display:inline-flex;align-items:center}
.theme-control select{width:90px;background:var(--surface);min-height:39px;border-radius:11px;font-size:12px}
main{padding-top:17px}.grid{display:grid;grid-template-columns:minmax(0,1.35fr) minmax(320px,1fr);gap:16px}.grid>section{min-width:0}
.panel{padding:21px;border:1px solid var(--white-line);border-radius:17px;background:var(--surface);box-shadow:var(--shadow)}.panel+.panel{margin-top:16px}
h2{font-size:19px;letter-spacing:-.02em;margin:0 0 4px}h3{font-size:15px;margin:23px 0 10px}
.panel-head{margin-bottom:17px}.section-note,.muted,header p{color:var(--muted);font-size:12px;line-height:1.7}
.switch{width:100%;height:auto;display:flex;justify-content:space-between;align-items:center;min-height:57px;padding:12px 14px;border:1px solid var(--line);border-radius:13px;background:var(--soft);gap:10px}
.switch::before{display:none}.switch+.switch{margin-top:9px}.switch-label{font-size:14px}.status-chip{background:var(--good-soft);color:var(--good);font-size:11px;padding:4px 9px;border-radius:999px}.status-chip.off{background:var(--soft-2);color:var(--muted)}
label{font-size:13px;font-weight:600;margin:14px 0 6px}.check-label{min-height:40px}.schedule{gap:7px}.day-row{min-height:47px;gap:9px}
input[type=text],input[type=password],input[type=url],input[type=tel],input[type=time],textarea,select{min-height:42px;border:1px solid var(--line);border-radius:11px;background:var(--soft);color:var(--ink);padding:9px 11px}
input[type=checkbox],input[type=range]{accent-color:var(--blue)}.day-row input[type=time]:disabled{background:var(--soft);opacity:.6}.rule-note{font-size:12px;line-height:1.7;color:var(--muted)}
.range-field{margin-top:20px;border-color:var(--line)}.range-field output{color:var(--blue);font-size:19px}.media-options{border:1px solid var(--line);border-radius:12px;background:var(--soft);padding:14px;margin-top:20px}
button{min-height:40px;border:1px solid var(--line);border-radius:11px;background:var(--surface);color:var(--ink);font-size:13px}button.primary{border:0;background:var(--primary);color:#fff!important}
.actions{gap:8px;margin-top:17px}.notice{font-size:12px;color:var(--bad);line-height:1.6}.notice:empty{display:none}.notice.success{color:var(--good)}
.knowledge-item{background:var(--soft);border:1px solid var(--line);border-radius:11px;padding:11px 12px}.knowledge-actions{gap:7px}.knowledge-name{font-size:13px}.knowledge-meta{font-size:11px;color:var(--muted)}
.preview{background:var(--soft);border-color:var(--line);border-radius:12px}.danger{color:var(--bad)}.knowledge-list{margin-top:14px}
html[data-theme="night"] .shell{background:rgba(24,31,52,.78)}html[data-theme="night"] header{background:linear-gradient(118deg,#294569,#303858 57%,#40345e 86%,#294a5e)}
@media(max-width:1023px){.shell{width:calc(100% - 28px);padding:18px;margin:14px auto}.grid{grid-template-columns:minmax(0,1.2fr) minmax(280px,1fr)}h1{font-size:25px}header{padding:19px}}
@media(max-width:759px){.shell{width:calc(100% - 16px);padding:11px;margin:8px auto;border-radius:18px}header{display:block;padding:17px;border-radius:15px}h1{font-size:24px}.header-actions{justify-content:flex-start;margin-top:14px;gap:8px}.grid{display:block}.grid>section+section{margin-top:14px}.panel{padding:16px;border-radius:15px}.panel+.panel{margin-top:14px}.day-row{grid-template-columns:45px 25px minmax(0,1fr);grid-template-rows:auto auto}.day-row input[type=time]:last-child{grid-column:3}.switch{padding:11px 12px}.switch-label{font-size:13px}.knowledge-item{flex-wrap:wrap}}
@media(max-width:759px){.shell input:not([type="checkbox"]):not([type="range"]),.shell textarea,.shell select{font-size:16px}}
@media(prefers-reduced-motion:reduce){*,*::before,*::after{transition:none!important;animation:none!important}}
'''

